glow.glsl:
shader_type canvas_item;

uniform vec4 glow_color : source_color = vec4(1.0, 0.8, 0.2, 1.0);
uniform float glow_intensity : hint_range(0.0, 5.0) = 1.5;
uniform float glow_size : hint_range(1.0, 20.0) = 4.0;
uniform float pulse_speed : hint_range(0.0, 10.0) = 0.0;

void fragment() {
	vec4 sprite_color = texture(TEXTURE, UV);

	// Inner glow: detect proximity to transparent edge
	vec2 ps = TEXTURE_PIXEL_SIZE * glow_size;

	// Sample neighbors to find minimum alpha (distance to edge)
	float min_alpha = 1.0;
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(-ps.x, -ps.y)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(0.0, -ps.y)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(ps.x, -ps.y)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(-ps.x, 0.0)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(ps.x, 0.0)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(-ps.x, ps.y)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(0.0, ps.y)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(ps.x, ps.y)).a);

	// Also sample at half distance for smoother gradient
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(-ps.x * 0.5, -ps.y * 0.5)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(ps.x * 0.5, -ps.y * 0.5)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(-ps.x * 0.5, ps.y * 0.5)).a);
	min_alpha = min(min_alpha, texture(TEXTURE, UV + vec2(ps.x * 0.5, ps.y * 0.5)).a);

	// Glow strength based on proximity to edge (where min_alpha < 1)
	float edge_proximity = 1.0 - min_alpha;

	float intensity = glow_intensity;
	if (pulse_speed > 0.0) {
		float pulse = sin(TIME * pulse_speed) * 0.5 + 0.5;
		intensity *= 1.0 + pulse * 0.3;
	}

	// Blend glow color with sprite color near edges
	vec3 final_rgb = mix(sprite_color.rgb, glow_color.rgb, edge_proximity * intensity * 0.5);

	COLOR = vec4(final_rgb, sprite_color.a);
}

innerGlow.glsl:
shader_type canvas_item;

uniform vec4 glow_color : source_color = vec4(1.0, 0.5, 0.0, 1.0);
uniform float glow_width : hint_range(0.0, 20.0) = 5.0;
uniform float glow_intensity : hint_range(0.0, 3.0) = 1.0;
uniform float glow_falloff : hint_range(0.5, 5.0) = 2.0;
uniform bool additive = true;

void fragment() {
	vec4 tex = texture(TEXTURE, UV);

	// WebGL doesn't support early return in fragment(), use if-else instead
	if (tex.a < 0.1) {
		COLOR = tex;
	} else {
		// Find distance to edge by sampling outward
		float min_dist = glow_width;

		for (float angle = 0.0; angle < 6.28318; angle += 0.5) {
			vec2 dir = vec2(cos(angle), sin(angle));

			for (float dist = 1.0; dist <= glow_width; dist += 1.0) {
				vec2 sample_uv = UV + dir * dist * TEXTURE_PIXEL_SIZE;
				float sample_alpha = texture(TEXTURE, sample_uv).a;

				if (sample_alpha < 0.1) {
					min_dist = min(min_dist, dist);
					break;
				}
			}
		}

		// Calculate glow based on distance to edge
		float glow = 1.0 - (min_dist / glow_width);
		glow = pow(glow, glow_falloff) * glow_intensity;

		vec3 result;
		if (additive) {
			result = tex.rgb + glow_color.rgb * glow;
		} else {
			result = mix(tex.rgb, glow_color.rgb, glow);
		}

		COLOR = vec4(result, tex.a);
	}
}

outline.glsl:
shader_type canvas_item;

uniform vec4 outline_color : source_color = vec4(1.0, 1.0, 0.0, 1.0);
uniform float outline_width : hint_range(0.0, 10.0) = 2.0;
uniform bool outline_only = false;

void fragment() {
	vec4 sprite_color = texture(TEXTURE, UV);

	// For Polygon2D: use inner outline (draw outline where neighbor is transparent)
	// Check if any neighboring pixel is transparent (outside the shape)
	vec2 ps = TEXTURE_PIXEL_SIZE * outline_width;

	float neighbor_alpha = 1.0;
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(-ps.x, -ps.y)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(0.0, -ps.y)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(ps.x, -ps.y)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(-ps.x, 0.0)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(ps.x, 0.0)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(-ps.x, ps.y)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(0.0, ps.y)).a);
	neighbor_alpha = min(neighbor_alpha, texture(TEXTURE, UV + vec2(ps.x, ps.y)).a);

	vec4 final_color;
	// Inner outline: current pixel is opaque but at least one neighbor is transparent
	if (sprite_color.a > 0.1 && neighbor_alpha < 0.1) {
		final_color = outline_color;
		final_color.a = sprite_color.a;
	} else if (outline_only) {
		final_color = vec4(0.0);
	} else {
		final_color = sprite_color;
	}
	COLOR = final_color;
}

dropShadow.glsl:
shader_type canvas_item;

uniform vec4 shadow_color : source_color = vec4(0.0, 0.0, 0.0, 0.5);
uniform vec2 shadow_offset = vec2(4.0, 4.0);
uniform float shadow_blur : hint_range(0.0, 10.0) = 2.0;
uniform bool shadow_only = false;

void fragment() {
	vec2 shadow_uv = UV - shadow_offset * TEXTURE_PIXEL_SIZE;

	// Calculate blurred shadow
	float shadow_alpha = 0.0;
	float total_weight = 0.0;

	if (shadow_blur > 0.0) {
		for (float x = -shadow_blur; x <= shadow_blur; x += 1.0) {
			for (float y = -shadow_blur; y <= shadow_blur; y += 1.0) {
				float dist = length(vec2(x, y));
				if (dist <= shadow_blur) {
					float weight = 1.0 - (dist / shadow_blur);
					vec2 offset = vec2(x, y) * TEXTURE_PIXEL_SIZE;
					shadow_alpha += texture(TEXTURE, shadow_uv + offset).a * weight;
					total_weight += weight;
				}
			}
		}
		shadow_alpha /= total_weight;
	} else {
		shadow_alpha = texture(TEXTURE, shadow_uv).a;
	}

	vec4 tex = texture(TEXTURE, UV);
	vec4 shadow = vec4(shadow_color.rgb, shadow_alpha * shadow_color.a);

	if (shadow_only) {
		COLOR = shadow;
	} else {
		// Composite: shadow behind, sprite on top
		COLOR = mix(shadow, tex, tex.a);
	}
}

tint.glsl:
shader_type canvas_item;

uniform vec4 tint_color : source_color = vec4(1.0, 1.0, 1.0, 1.0);
uniform float tint_amount : hint_range(0.0, 1.0) = 0.5;
uniform int blend_mode : hint_range(0, 4) = 0; // 0=multiply, 1=add, 2=screen, 3=overlay, 4=replace

void fragment() {
	vec4 tex = texture(TEXTURE, UV);
	vec3 result;

	if (blend_mode == 0) {
		// Multiply
		result = tex.rgb * tint_color.rgb;
	} else if (blend_mode == 1) {
		// Additive
		result = tex.rgb + tint_color.rgb * tint_amount;
	} else if (blend_mode == 2) {
		// Screen
		result = 1.0 - (1.0 - tex.rgb) * (1.0 - tint_color.rgb);
	} else if (blend_mode == 3) {
		// Overlay
		result = mix(
			2.0 * tex.rgb * tint_color.rgb,
			1.0 - 2.0 * (1.0 - tex.rgb) * (1.0 - tint_color.rgb),
			step(0.5, tex.rgb)
		);
	} else {
		// Replace
		result = tint_color.rgb;
	}

	COLOR = vec4(mix(tex.rgb, result, tint_amount), tex.a * tint_color.a);
}

pixelate.glsl:
shader_type canvas_item;

uniform float pixel_size : hint_range(2.0, 64.0) = 8.0;

void fragment() {
	vec2 tex_size = 1.0 / TEXTURE_PIXEL_SIZE;
	vec2 pixel_uv = floor(UV * tex_size / pixel_size) * pixel_size / tex_size;
	pixel_uv = clamp(pixel_uv, vec2(0.001), vec2(0.999));
	COLOR = texture(TEXTURE, pixel_uv);
}

waveDistortion.glsl:
shader_type canvas_item;

uniform float amplitude_x : hint_range(0.0, 0.2) = 0.02;
uniform float amplitude_y : hint_range(0.0, 0.2) = 0.02;
uniform float frequency_x : hint_range(0.0, 50.0) = 10.0;
uniform float frequency_y : hint_range(0.0, 50.0) = 10.0;
uniform float speed : hint_range(0.0, 10.0) = 2.0;

void fragment() {
	vec2 uv = UV;

	// Sine wave distortion
	uv.x += sin(uv.y * frequency_y + TIME * speed) * amplitude_x;
	uv.y += sin(uv.x * frequency_x + TIME * speed) * amplitude_y;

	// Clamp UV to prevent sampling outside texture
	uv = clamp(uv, vec2(0.0), vec2(1.0));

	COLOR = texture(TEXTURE, uv);
}
